function PVPArenaAgainstHeadSingleNode:RefreshUI(oneMatchChartData, isLastWheel, index, selfPlayerId)
    self.oneMatchChartData = oneMatchChartData

    local isShowEmptyNode   = false
    local isShowAdvancement = false
    local info, playerId, isLoser
    if not isLastWheel then
        -------------------------------------------------
        --- 非最后一轮是展示
        --- 1. 检查 oneMatchChartData 是否为nil
        isShowEmptyNode = oneMatchChartData == nil
        --- 2. 检查 info 是否为nil
        if not isShowEmptyNode then
            --- index 从0开始
            local isLeft = index % 2 == 0
            info = isLeft and oneMatchChartData.leftInfo or oneMatchChartData.rightInfo
            isShowEmptyNode = info == nil

            if not isShowEmptyNode then
                playerId = isLeft and oneMatchChartData.leftPlayerId or oneMatchChartData.rightPlayerId
                local leftScore        = checkNumber(oneMatchChartData.leftScore)
                local rightScore       = checkNumber(oneMatchChartData.rightScore)
                if leftScore ~= rightScore then
                    if isLeft then
                        isLoser = leftScore < rightScore
                    else
                        isLoser = rightScore < leftScore
                    end
                end
            end

        end

    else
        -------------------------------------------------
        --- 如果最后一轮是展示 晋级节点 所以oneMatchChartData必是空的
        isShowAdvancement = oneMatchChartData == nil
        if not isShowAdvancement then
            --- 最后一轮是展示轮只有左侧数据
            playerId = oneMatchChartData.leftPlayerId
            info = oneMatchChartData.leftInfo
        end

    end

    KTool.SetActive(self.ImgBg1.gameObject,    isShowEmptyNode)
    KTool.SetActive(self.ImgBg2.gameObject,    isShowAdvancement)

    local isShowHeadGroup = info ~= nil
    KTool.SetActive(self.HeadGroup.gameObject, isShowHeadGroup)
    playerId = checkNumber(playerId)

    if isShowHeadGroup then
        self:RefreshHeadGroupNode(info, playerId, selfPlayerId, isLoser)
    end
end

---RefreshHeadGroupNode
---@param info table
function PVPArenaAgainstHeadSingleNode:RefreshHeadGroupNode(info, playerId, selfPlayerId, isLoser)
    ---@type PVPArenaAgainstHeadGroupNode
    local env = CfUtils.GetLuaScr(self.HeadGroup.gameObject, PVPArenaAgainstHeadGroupNodePath)
    if isNull(env) then return end
    env:SetOneMatchChartData(self.oneMatchChartData)
    --local pvpArenaEntryDojo = pvpArenaComponent:GetPVPArenaEntryDojo()
    --local battleStatus      = checkNumber(pvpArenaEntryDojo.battleStatus)
    --local mainPanelStatus   = pvpArenaComponent:GetMainPanelStatus()
    --local state             = PVPArenaUtils.InitMatchChartClickState(self.isAudience, isPlayerSelf, battleStatus, mainPanelStatus)
    --env:SetState(state)
    env:SetSelfPlayerId(selfPlayerId)
    local quizzedMap = pvpArenaComponent:GetQuizzedMap()
    local isQuizzed = quizzedMap[tostring(playerId)] ~= nil
    env:RefreshUI(info, playerId, false, isLoser, isQuizzed)
end

